function currentLang(){return localStorage.getItem("voce-lang")||"en"}
function renderInstitution(l){
 const p=PAGES[window.VOCE_PAGE][l]||PAGES[window.VOCE_PAGE].en;
 const c=COMMON[l]||COMMON.en;
 document.documentElement.lang=l;
 document.title=p.title+" — VOCE";
 document.querySelectorAll("[data-lang]").forEach(b=>b.classList.toggle("active",b.dataset.lang===l));
 document.querySelector("[data-nav-research]").textContent=c.navResearch;
 document.querySelector("[data-nav-standards]").textContent=c.navStandards;
 document.querySelector("[data-nav-publications]").textContent=c.navPublications;
 document.querySelector("[data-nav-about]").textContent=c.navAbout;
 document.querySelector("#page-kicker").textContent=p.kicker;
 document.querySelector("#page-title").textContent=p.title;
 document.querySelector("#page-deck").textContent=p.deck;
 document.querySelector("#page-meta").innerHTML=p.meta.map(x=>'<span>'+x+'</span>').join("");
 const sections=document.querySelector("#sections");
 sections.innerHTML=p.sections.map(s=>'<section class="chapter"><div class="chapter-no">'+s[0]+'</div><h2>'+s[1]+'</h2>'+s.slice(2).map((x,i)=>'<p'+(i===0&&s.length>4?' class="signal"':'')+'>'+x+'</p>').join("")+'</section>').join("");
 document.querySelector("#links-title").textContent=p.linksTitle;
 document.querySelector("#links").innerHTML=p.links.map(x=>'<a class="link-row" href="'+x[2]+'"'+(x[2].startsWith("http")?' target="_blank" rel="noopener"':'')+'><div class="label">'+c.links+'</div><div><h3>'+x[0]+'</h3><p>'+x[1]+'</p></div><div class="go">'+(l==="fr"?"Ouvrir":l==="it"?"Apri":"Open")+'</div></a>').join("");
 document.querySelector("#f-inst").textContent=c.institution;
 document.querySelector("#f-work").textContent=c.work;
 document.querySelector("#f-about").textContent=c.navAbout;
 document.querySelector("#f-standards").textContent=c.navStandards;
 document.querySelector("#f-contact").textContent=c.contact;
 document.querySelector("#f-research").textContent=c.navResearch;
 document.querySelector("#f-ai").textContent=l==="fr"?"Gouvernance de l’IA":l==="it"?"Governance dell’IA":"AI Governance";
 document.querySelector("#f-pubs").textContent=c.navPublications;
}
function setLang(l){localStorage.setItem("voce-lang",l);renderInstitution(l)}
document.addEventListener("DOMContentLoaded",()=>{
 document.querySelectorAll("[data-lang]").forEach(b=>b.addEventListener("click",()=>setLang(b.dataset.lang)));
 renderInstitution(currentLang());
});